from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void = {'meta','br','hr','circle','line','rect','path','polygon','text','stop','defs','feGaussianBlur','feMerge','feMergeNode'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.stack:
            self.stack.remove(tag)
c = Checker()
with open('dashboard.html') as f:
    c.feed(f.read())
print(f'Unclosed tags: {c.stack[:20]}...' if c.stack else 'All tags properly closed')
